import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {execFileSync, spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
process.chdir(root);
const hash = data => crypto.createHash('sha256').update(data).digest('hex');
const historicalRevision = '3e55656';
const conditions = [
  {id: 'historical-default', source: 'historical', args: []},
  {id: 'prepared-default', source: 'prepared', args: []},
  {id: 'current-default', source: 'current', args: []},
  {id: 'baseline', source: 'current', args: ['baseline']},
  {id: 'full', source: 'current', args: ['full']},
  {id: 'without-unicode', source: 'current', args: ['without-unicode']},
  {id: 'without-escaping', source: 'current', args: ['without-escaping']},
];
// Exact bytes matter: the CLI emits one record and a final LF. No trimming.
function grade(observation, expected) {
  if (observation.error || observation.signal || observation.status === null)
    return {pass: false, type: 'infrastructure', reason: 'process could not complete'};
  if (observation.status !== 0)
    return {pass: false, type: 'execution', reason: 'nonzero exit'};
  if (observation.stdout !== expected)
    return {pass: false, type: 'output', reason: 'stdout differs from expected CSV bytes'};
  return {pass: true, type: 'pass', reason: 'exact CSV bytes match'};
}
function selfTest() {
  const ok = stdout => ({status: 0, signal: null, stdout});
  assert(grade(ok('a,b\n'), 'a,b\n').pass);
  assert(!grade(ok('b,a\n'), 'a,b\n').pass);
  assert(!grade(ok('a,b'), 'a,b\n').pass);
  assert(!grade(ok('a,b \n'), 'a,b\n').pass);
  assert(!grade(ok('a,b\n\n'), 'a,b\n').pass);
  assert(!grade({...ok('a,b\n'), status: 1}, 'a,b\n').pass);
  assert.equal(grade({status: null, error: 'spawn'}, '').type, 'infrastructure');
  // Equivalent JS constructions produce identical bytes; transformed stdout must not pass.
  for (const [program, expectedPass] of [
    ['console.log(["a","b"].join(","))', true],
    ['process.stdout.write("a,b\\n")', true],
    ['process.stdout.write("a,b\\n".trimEnd())', false],
  ]) {
    const observed = spawnSync(process.execPath, ['-e', program], {encoding: 'utf8'});
    assert.equal(grade(observed, 'a,b\n').pass, expectedPass);
  }
}
selfTest();
const [mode, filename] = process.argv.slice(2);
if (!['--run', '--replay'].includes(mode) || !filename)
  throw Error('Usage: node eval/run.mjs --run|--replay RESULTS.json');
if (mode === '--replay') {
  const saved = JSON.parse(fs.readFileSync(filename, 'utf8'));
  for (const [name, source] of Object.entries(saved.sources))
    assert.equal(hash(source.text), source.sha256, `${name} hash`);
  assert.equal(hash(JSON.stringify(saved.cases)), saved.casesSha256);
  for (const row of saved.results) {
    const task = saved.cases.find(task => task.id === row.case);
    assert(task);
    assert.deepEqual(grade(row.observation, task.expected), row.rating);
  }
  assert.equal(saved.results.length, saved.conditions.length * saved.cases.length);
  console.log(`Replayed ${saved.results.length} saved ratings; grader self-tests passed.`);
} else {
  // Freeze all source and task bytes before executing any candidate.
  const historical = execFileSync('git', ['show', `${historicalRevision}:app.mjs`], {encoding: 'utf8'});
  const prepared = historical.replace("|| 'baseline'", "|| 'full'");
  assert.notEqual(prepared, historical);
  const sources = Object.fromEntries(Object.entries({
    historical, prepared, current: fs.readFileSync('app.mjs', 'utf8'),
  }).map(([name, text]) => [name, {text, sha256: hash(text)}]));
  const cases = JSON.parse(fs.readFileSync('eval/cases.json', 'utf8'));
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'csv-export-'));
  const results = [];
  try {
    for (const [name, source] of Object.entries(sources))
      fs.writeFileSync(path.join(directory, `${name}.mjs`), source.text);
    // Interleave conditions on the same task. These are deterministic CLI calls, not model samples.
    for (const task of cases) for (const condition of conditions) {
      const run = spawnSync(process.execPath, [path.join(directory, `${condition.source}.mjs`),
        JSON.stringify(task.input), ...condition.args], {encoding: 'utf8', timeout: 5000});
      const observation = {status: run.status, signal: run.signal, stdout: run.stdout ?? '',
        stderr: run.stderr ?? '', error: run.error?.code ?? null};
      results.push({condition: condition.id, case: task.id, observation,
        rating: grade(observation, task.expected)});
    }
  } finally {
    fs.rmSync(directory, {recursive: true, force: true});
  }
  const record = {runtime: process.version, historicalRevision,
    runnerSha256: hash(fs.readFileSync('eval/run.mjs')), sources, cases,
    casesSha256: hash(JSON.stringify(cases)), conditions, results};
  fs.writeFileSync(filename, JSON.stringify(record, null, 2) + '\n', {flag: 'wx'});
  for (const condition of conditions) {
    const rows = results.filter(row => row.condition === condition.id);
    console.log(`${condition.id}: ${rows.filter(row => row.rating.pass).length}/${rows.length}`);
  }
  if (results.some(row => row.rating.type === 'infrastructure' ||
      (['current-default', 'full'].includes(row.condition) && !row.rating.pass)))
    process.exitCode = 1;
}
EOF
